contract SnipingBotV3 is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public owner;
    IUniswapV2Router02 public uniswapRouter;
    uint256 public autoWithdrawThreshold = 0.5 ether; // Auto-withdraw ETH when balance reaches 0.5 ETH

    event TokenSniped(address indexed token, uint256 ethAmount);
    event TokenSold(address indexed token, uint256 tokenAmount);
    event ETHWithdrawn(uint256 amount);
    event TokensWithdrawn(address indexed token, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not contract owner");
        _;
    }

    constructor(address _router) {
        require(_router != address(0), "Invalid router address");
        owner = msg.sender;
        uniswapRouter = IUniswapV2Router02(_router);
    }

    /// @notice Snipes a token with ETH, pre-approving for auto-sell
    function snipeToken(address token, uint256 amountOutMin) external payable onlyOwner nonReentrant {
        require(msg.value > 0, "Must send ETH to snipe");
        require(token != address(0), "Invalid token address");
        require(_isContract(token), "Invalid token contract");

        address WETH = uniswapRouter.WETH();
        address pair = IUniswapV2Factory(uniswapRouter.factory()).getPair(WETH, token);
        require(pair != address(0), "No valid Uniswap pair found");

        // ✅ FIX: Declare the path array within the function
        address[] memory path = new address[](2);
        path[0] = WETH;
        path[1] = token;

        uint256[] memory amounts = uniswapRouter.swapExactETHForTokens{value: msg.value}(
            amountOutMin,
            path,
            address(this),
            block.timestamp + 300
        );
        require(amounts[amounts.length - 1] >= amountOutMin, "Swap failed");

        // ✅ FIX: Use `safeIncreaseAllowance()` instead of `safeApprove()`
        IERC20(token).safeIncreaseAllowance(address(uniswapRouter), type(uint256).max);

        emit TokenSniped(token, msg.value);
    }

    /// @notice Automatically sells tokens when profit target is reached
    function autoSell(address token, uint256 amountOutMin) external onlyOwner nonReentrant {
        require(token != address(0), "Invalid token address");
        require(_isContract(token), "Invalid token contract");

        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to sell");

        address WETH = uniswapRouter.WETH();
        
        // ✅ FIX: Declare the path array within the function
        address[] memory path = new address[](2);
        path[0] = token;
        path[1] = WETH;

        uint256 beforeETH = address(this).balance;
        uniswapRouter.swapExactTokensForETH(
            balance,
            amountOutMin,
            path,
            address(this),
            block.timestamp + 300
        );
        uint256 afterETH = address(this).balance;
        uint256 ethReceived = afterETH - beforeETH;
        require(ethReceived > 0, "No ETH received");

        emit TokenSold(token, balance);
        
        // Auto-withdraw ETH if balance exceeds threshold
        if (address(this).balance >= autoWithdrawThreshold) {
            withdrawETH();
        }
    }

    /// @notice Withdraws all ETH from the contract to the owner.
    function withdrawETH() public onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No ETH to withdraw");
        payable(owner).transfer(balance);
        emit ETHWithdrawn(balance);
    }

    /// @notice Withdraws any ERC20 token from the contract to the owner.
    function withdrawTokens(address token) external onlyOwner nonReentrant {
        require(token != address(0), "Invalid token address");
        require(_isContract(token), "Invalid token contract");

        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");

        IERC20(token).safeTransfer(owner, balance);
        emit TokensWithdrawn(token, balance);
    }

    /// @dev Checks if an address is a contract.
    function _isContract(address addr) private view returns (bool) {
        uint256 size;
        assembly {
            size := extcodesize(addr)
        }
        return size > 0;
    }

    /// @notice Allows the contract to receive ETH from Uniswap swaps.
    receive() external payable {}
}
